{"implementation": "def solve(case):
    import math
    required = ['sentence_vectors', 'query_vector', 'context_weight']
    for k in required:
        if k not in case:
            raise ValueError(f"Missing required field: {k}")
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']
    if not isinstance(sentence_vectors, list) or len(sentence_vectors) == 0:
        raise ValueError("sentence_vectors must be a non-empty list")
    if not isinstance(query_vector, list) or len(query_vector) == 0:
        raise ValueError("query_vector must be a non-empty list")
    dim = len(query_vector)
    for i, vec in enumerate(sentence_vectors):
        if not isinstance(vec, list) or len(vec) != dim:
            raise ValueError(f"sentence_vectors[{i}] has invalid dimensions")
    if not isinstance(context_weight, (int, float)):
        raise ValueError("context_weight must be numeric")
    n = len(sentence_vectors)
    similarities = []
    for vec in sentence_vectors:
        dot = sum(a*b for a,b in zip(vec, query_vector))
        norm_vec = math.sqrt(sum(a*a for a in vec))
        norm_q = math.sqrt(sum(a*a for a in query_vector))
        if norm_vec == 0 or norm_q == 0:
            sim = 0.0
        else:
            sim = dot / (norm_vec * norm_q)
        similarities.append(sim)
    neighbor_scores = []
    for i in range(n):
        neighbors = []
        if i-1 >= 0:
            neighbors.append(similarities[i-1])
        if i+1 < n:
            neighbors.append(similarities[i+1])
        if neighbors:
            avg = sum(neighbors) / len(neighbors)
        else:
            avg = 0.0
        neighbor_scores.append(avg)
    scores = []
    for i in range(n):
        own = similarities[i]
        neighbor = neighbor_scores[i]
        blended = (1 - context_weight) * own + context_weight * neighbor
        scores.append(blended)
    scores = [round(score, 6) for score in scores]
    indices = list(range(n))
    indices.sort(key=lambda i: (-scores[i], i))
    rankings = indices
    return {"scores": scores, "rankings": rankings}"}
